package com.example.dsatracker.controller;import com.example.dsatracker.dto.UserRequestDTO;import com.example.dsatracker.dto.UserResponseDTO;import com.example.dsatracker.service.UserService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/users")public class UserController {    private final UserService service;    public UserController(UserService service) {        this.service = service;    }    @PostMapping    public ResponseEntity<UserResponseDTO> createUser(            @Valid @RequestBody UserRequestDTO request) {        UserResponseDTO response = service.createUser(request);        return ResponseEntity                .status(HttpStatus.CREATED)                .body(response);    }}